import json

# Fix: PRESERVE row 0 exactly as in input (all 2s)
color_offset = {
    3: -2, 4: -4, 5: -4, 6: -6, 7: -1, 8: -4, 2: 0
}

def get_offset(color):
    if color in color_offset:
        return color_offset[color]
    if color % 2 == 0:
        return -(color // 2)
    return -2

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    output = [[0] * cols for _ in range(rows)]

    # PRESERVE row 0 exactly (anchor row)
    output[0] = list(grid[0])

    # For other rows: apply color shifts
    for r in range(1, rows):
        output[r][0] = grid[r][0]  # Keep anchor color in col 0
        for c in range(1, cols):
            color = grid[r][c]
            if color != 0:
                offset = get_offset(color)
                out_c = c + offset
                if 1 <= out_c < cols:
                    output[r][out_c] = color

    return output

